void appendEmbeddedV8UvInlineProbePayload(
        std::vector<std::string>& payload,
        void* handle,
        EmbeddedLifecycleJsProbeKind kind
) {
    const auto* selectorFlags = embeddedInlineProbeSelectorFlags(kind);
    if (selectorFlags == nullptr) {
        return;
    }
    appendEmbeddedV8UvIsolateLifecycleProbePayload(
            payload,
            handle,
            true,
            true,
            true,
            true,
            true,
            true,
            true,
            false,
            false,
            false,
            embeddedInlineProbeStdoutCapture(kind),
            selectorFlags->jsResult,
            selectorFlags->stdoutWriteRequested,
            selectorFlags->consoleDiagnostics,
            selectorFlags->consoleStream,
            selectorFlags->consoleShape,
            selectorFlags->consoleReplaceRequested,
            selectorFlags->consoleFamilyRequested,
            selectorFlags->consoleFormatRequested,
            selectorFlags->consoleRejectionRequested,
            selectorFlags->consoleUncaughtRequested,
            selectorFlags->schedulingRequested,
            selectorFlags->schedulingOrderRequested
    );
}

jobjectArray nativeEmbeddedProbeInlineKind(
        JNIEnv* env,
        EmbeddedLifecycleJsProbeKind kind,
        int probeLevel
) {
    const auto startedAt = Clock::now();
    std::string logToken = embeddedInlineProbeLogName(kind) == nullptr
            ? "v8.uv.inline_unknown.lifecycle"
            : embeddedInlineProbeLogName(kind);
    for (char& ch : logToken) {
        if (ch == '.') {
            ch = '_';
        }
    }
    __android_log_print(ANDROID_LOG_INFO, kLogTag, "probe.%s.enter level=%d", logToken.c_str(), probeLevel);
    std::vector<std::string> payload;
    void* handle = probeLoadedLibnodeHandle(payload);
    appendEmbeddedV8UvInlineProbePayload(payload, handle, kind);
    putCommonEmbeddedProbePayload(payload, probeLevel, startedAt);
    __android_log_print(ANDROID_LOG_INFO, kLogTag, "probe.%s.exit level=%d", logToken.c_str(), probeLevel);
    return toJavaStringArray(env, payload);
}

